import React from 'react';
import { NavLink } from 'react-router-dom';

export type FeatureItem = {
  id: string;
  label: string;
  path?: string;
  icon?: string;
};

const defaultFeatures: FeatureItem[] = [
  { id: 'dashboard', label: 'Dashboard', path: '/dashboard', icon: '⊞' },
  { id: 'users',     label: 'Users',     path: '/users',     icon: '👥' },

];

interface SidebarProps {
  features?: FeatureItem[];
  collapsed?: boolean;
  onToggle?: () => void;
}

export const Sidebar: React.FC<SidebarProps> = ({
  features = defaultFeatures,
  collapsed = false,
  onToggle,
}) => {
  const width = collapsed ? 56 : 280;

  return (
    <aside style={{
      width,
      minWidth: width,
      height: '100vh',
      background: '#F9FBFC',
      borderRight: '1px solid #E1E4EA',
      boxSizing: 'border-box',
      padding: collapsed ? '12px 8px' : '12px 16px 12px 12px',
      display: 'flex',
      flexDirection: 'column',
      gap: 24,
      transition: 'width 0.25s ease, min-width 0.25s ease, padding 0.25s ease',
      overflow: 'hidden',
      position: 'fixed',
      top: 0,
      left: 0,
      zIndex: 100,
    }}>
      {/* Logo / Brand area */}
      {/* Brand + toggle */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <button
          onClick={onToggle}
          title={collapsed ? 'Open sidebar' : 'Toggle sidebar'}
          style={{
            width: 36,
            height: 36,
            borderRadius: 8,
            border: 'none',
            background: 'transparent',
            cursor: 'pointer',
            fontSize: 18,
          }}
        >
          ☰
        </button>
        {!collapsed && (
          <div style={{
            fontSize: 15,
            fontWeight: 700,
            color: '#0f172a',
            padding: '4px 4px 0',
            whiteSpace: 'nowrap',
          }}>
            Admin Panel
          </div>
        )}
      </div>

      <nav style={{ flex: 1 }}>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: 4 }}>
          {features.map(f => (
            <li key={f.id}>
              <NavLink
                to={f.path || '#'}
                title={collapsed ? f.label : undefined}
                style={({ isActive }) => ({
                  color: isActive ? '#0b69ff' : '#4B5565',
                  textDecoration: 'none',
                  fontWeight: isActive ? 600 : 400,
                  fontSize: 14,
                  display: 'flex',
                  alignItems: 'center',
                  gap: 10,
                  padding: '8px 10px',
                  borderRadius: 8,
                  background: isActive ? '#EFF4FF' : 'transparent',
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  transition: 'background 0.15s ease, color 0.15s ease',
                })}
              >
                <span style={{ fontSize: 16, flexShrink: 0 }}>{f.icon}</span>
                {!collapsed && <span>{f.label}</span>}
              </NavLink>
            </li>
          ))}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
